const GalleryPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  const [modalImages, setModalImages] = React.useState<ImageItem[]>([]);
  const [pendingOpen, setPendingOpen] = React.useState(false);
  const openModalRef = React.useRef<((startIndex?: number) => void) | null>(
    null,
  );

  const openGallery = (images: ImageItem[]) => {
    setModalImages(images);
    setPendingOpen(true);
  };

  React.useEffect(() => {
    if (!pendingOpen || modalImages.length === 0) return;
    if (!openModalRef.current) return;
    openModalRef.current(0);
    setPendingOpen(false);
  }, [pendingOpen, modalImages]);

  const galleries = galleryCollections.map((collection) => {
    const label = t(collection.titleKey) as string;
    const basePath = collection.folder
      ? `/gallery/${collection.folder}`
      : "/gallery";
    const images = collection.files.map((file, index) => ({
      src: encodeURI(`${basePath}/${file}`),
      alt: `${label} ${index + 1}`,
      caption: label,
    }));

    return { ...collection, label, images };
  });

  return (
    <Layout data={companyData}>
      <section>
        <ImageModal
          images={modalImages}
          trigger={(open) => {
            openModalRef.current = open;
            return null;
          }}
        />

        <section className="text-terracota bg-beige px-12 py-6 mb-6 shadow-lg">
          <h2 className={styles.title}>{t("menu.gallery")}</h2>

          <article className="grid gap-1 my-12 w-full mx-auto">
            {galleries.map((gallery, index) => (
              <button
                key={gallery.id}
                type="button"
                className={`group text-terracota flex w-full flex-col items-center px-6 py-4 text-center transition duration-200 hover:-translate-y-1 `}
                onClick={() => openGallery(gallery.images)}
              >
                <img
                  src={gallery.icon}
                  alt={gallery.label}
                  width={1398}
                  height={1400}
                  className="mb-4 h-96 w-auto object-contain"
                  loading="lazy"
                  decoding="async"
                />
                <span className="body_mobile sm:body_desk">
                  {gallery.label}
                </span>
              </button>
            ))}
          </article>
        </section>
      </section>
    </Layout>
  );
};

export default GalleryPage;

export const Head: HeadFC<any> = ({ data, pageContext }) => (
  <SEO
    data={companyData}
    localesData={data?.locales?.edges?.[0]?.node?.data}
    language={(pageContext as any)?.i18n?.language}
    languages={(pageContext as any)?.i18n?.languages}
    defaultLanguage={(pageContext as any)?.i18n?.defaultLanguage}
    originalPath={(pageContext as any)?.i18n?.originalPath}
    titleKey="gallery.metaTitle"
    descriptionKey="gallery.metaDescription"
    authorKey="gallery.metaAuthor"
    pathname="/gallery/"
    schemaType="ProfessionalService"
  />
);

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

